 private boolean punish(CommandSender s,String[] a,PunishmentType type,String perm){if(!perm(s,perm))return true;if(a.length==0){if(s instanceof Player x)p.gui().openPlayers(x,0);return true;}Player t=target(a[0]); if(t==null && type==PunishmentType.IP_BAN && a[0].matches("(?:\\d{1,3}\\.){3}\\d{1,3}")){java.util.UUID iu=java.util.UUID.nameUUIDFromBytes(("IP:"+a[0]).getBytes(java.nio.charset.StandardCharsets.UTF_8));long dur=a.length>1?DurationUtil.parse(a[1]):0;int from=dur>0?2:1;if(dur<0)dur=0;if(dur>30L*86400){s.sendMessage(Text.c("<yellow>⚠</yellow> ᴜʟᴛʀᴀs | Maximum temporary duration is 30 days."));return true;}String r=reason(a,from);p.punishments().apply(iu,"IP:"+a[0],a[0],type,dur,r,s instanceof Player?(Player)s:null,"PLAYER").thenAccept(ok->Bukkit.getScheduler().runTask(p,()->s.sendMessage(Text.c(ok?"<green>✓</green> ᴜʟᴛʀᴀs | IP punishment applied.":"<yellow>⚠</yellow> ᴜʟᴛʀᴀs | IP already punished."))));return true;} if(t==null){s.sendMessage(Text.c("<red>✕</red> ᴜʟᴛʀᴀs | Player not found."));return true;}if(a.length==1){if(s instanceof Player x){p.gui().select(x,t.getUniqueId());p.gui().openDuration(x,type.name());}return true;}long dur=DurationUtil.parse(a[1]);int from=2;if(dur<0){dur=0;from=1;}if(dur>30L*86400){s.sendMessage(Text.c("<yellow>⚠</yellow> ᴜʟᴛʀᴀs | Maximum temporary duration is 30 days."));return true;}String r=reason(a,from);String ip=t.getAddress()==null?"":t.getAddress().getAddress().getHostAddress();p.punishments().apply(t.getUniqueId(),t.getName(),ip,type,dur,r,s instanceof Player?(Player)s:null,"PLAYER").thenAccept(ok->Bukkit.getScheduler().runTask(p,()->s.sendMessage(Text.c(ok?"<green>✓</green> ᴜʟᴛʀᴀs | Punishment applied successfully.":"<yellow>⚠</yellow> ᴜʟᴛʀᴀs | Player already has this punishment."))));return true;}
 private boolean remove(CommandSender s,String[] a,PunishmentType t,String perm){if(!perm(s,perm))return true;if(a.length==0){if(s instanceof Player x)p.gui().openPlayers(x,0);return true;}Player x=target(a[0]);UUID u=x!=null?x.getUniqueId():null;if(u==null)try{u=UUID.fromString(a[0]);}catch(Exception ignored){}if(u==null)return true;UUID id=u;p.punishments().remove(id,t,s instanceof Player?(Player)s:null).thenAccept(ok->Bukkit.getScheduler().runTask(p,()->s.sendMessage(Text.c(ok?"<green>✓</green> ᴜʟᴛʀᴀs | Punishment removed.":"<yellow>⚠</yellow> ᴜʟᴛʀᴀs | No active punishment."))));return true;}
