 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] a){String n=c.getName().toLowerCase(Locale.ROOT);List<String> base=List.of("ban","ipban","ip_ban","mute","warn","freeze","jail","vn","kick","unban","unmute","unjail","reload","list","logs");if(a.length==1){if(n.equals("tam")||n.equals("admin"))return base;return Bukkit.getOnlinePlayers().stream().map(Player::getName).filter(x->x.toLowerCase().startsWith(a[0].toLowerCase())).sorted().toList();}if(a.length==2&&List.of("ban","mute","ipban","ip_ban","tam").contains(n))return List.of("1m","10m","30m","1h","6h","1d","7d","1w","30d");return Collections.emptyList();}
